from __future__ import annotations

from apc_core.packing_drawer_ui import packing_drawer_html


def order_invoice_html(*, include_fixture_drawer: bool = False, include_core_drafts: bool = False) -> str:
    fixture_drawer = packing_drawer_html() if include_fixture_drawer else ""
    core_draft_tab = '<button id="order-invoice-tab-core-draft" class="tab" type="button" role="tab" aria-selected="false" aria-controls="order-invoice-tabpanel" tabindex="-1" data-type="core_draft">Core Drafts</button>' if include_core_drafts else ""
    html = """<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APC Core · Order/Invoice</title>
<style>:root{--ink:#24272b;--muted:#68717c;--line:#e5e1db;--cream:#eadbc8;--paper:#fffdfa;--accent:#1d6b57;--tint:#dcefe5}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{max-width:1120px;margin:auto;padding:28px}.back{color:var(--accent);font-weight:700}.card,.dialog{background:var(--paper);border:1px solid var(--line);border-radius:16px;box-shadow:4px 4px 0 #24272b22}.card{padding:24px}.open{background:var(--accent);color:#fff;border:0;border-radius:10px;padding:11px 14px;font:inherit;font-weight:700;cursor:pointer}.modal{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:18px;background:#24272b88}.modal[hidden]{display:none}.dialog{width:min(900px,100%);max-height:90vh;overflow:auto;padding:20px}.toolbar,.tabs,.controls,.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.toolbar{justify-content:space-between}.tab,.secondary{background:#fff;color:var(--accent);border:1px solid var(--line);border-radius:9px;padding:9px 11px;font:inherit;font-weight:700;cursor:pointer}.tab[aria-selected="true"]{background:var(--accent);color:#fff}.controls input{min-width:220px;flex:1;padding:10px;border:1px solid var(--line);border-radius:9px;font:inherit}.authority{margin:14px 0;padding:9px 11px;border-left:4px solid var(--accent);background:var(--tint);font-weight:800;letter-spacing:.04em}.results{margin:0;padding:0;list-style:none}.result{width:100%;margin:7px 0;padding:12px;text-align:left;background:#fff;border:1px solid var(--line);border-radius:10px;cursor:pointer}.result[aria-pressed="true"]{background:var(--tint);outline:3px solid var(--accent)}.meta{display:block;color:var(--muted);font-size:12px;margin-top:4px}.detail{min-height:38px;color:var(--muted)}button:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:2px}@media(max-width:620px){.shell{padding:16px}.dialog{padding:15px}.controls input{min-width:100%}}</style>
<body><main id="order-invoice-workspace" class="shell"><a class="back" href="../">Main menu</a><section class="card"><p>Read-only source browsing. Records remain separate; this workspace does not create a relationship between them.</p><button id="open-order-invoice" class="open" type="button">Open Order/Invoice</button></section></main>
<section id="order-invoice-modal" class="modal" role="dialog" aria-modal="true" aria-labelledby="order-invoice-title" hidden><div class="dialog"><div class="toolbar"><h1 id="order-invoice-title">Order/Invoice</h1><button id="close-order-invoice" class="secondary" type="button">Close</button></div><div id="order-invoice-tabs" class="tabs" role="tablist" aria-label="Order and invoice record filters"><button id="order-invoice-tab-source-order" class="tab" type="button" role="tab" aria-selected="true" aria-controls="order-invoice-tabpanel" tabindex="0" data-type="source_order">Source Orders</button><button id="order-invoice-tab-source-invoice" class="tab" type="button" role="tab" aria-selected="false" aria-controls="order-invoice-tabpanel" tabindex="-1" data-type="source_invoice">Legacy Invoices · Read-only</button><!-- CORE_DRAFT_TAB --></div><section id="order-invoice-tabpanel" role="tabpanel" aria-labelledby="order-invoice-tab-source-order"><p id="order-invoice-authority" class="authority">SOURCE ORDER · READ-ONLY</p><div class="controls"><input id="order-invoice-query" aria-label="Search selected records" autocomplete="off"><button id="browse-order-invoice" class="open" type="button">Browse</button><button id="order-invoice-language-toggle" class="secondary" type="button" aria-pressed="false">ไทย</button></div><p id="order-invoice-status" class="meta" aria-live="polite">Enter a search value to browse the selected records.</p><ul id="order-invoice-results" class="results" aria-label="Browse results"></ul><div class="actions"><button id="order-invoice-prev-page" class="secondary" type="button">Previous results page</button><label id="order-invoice-page-label">Results page <input id="order-invoice-page-jump" type="number" min="1" value="1"></label><button id="order-invoice-next-page" class="secondary" type="button">Next results page</button><button id="open-order-invoice-result" class="secondary" type="button">Open selected</button></div><section id="order-invoice-line-window" class="detail" data-language="english"></section><p id="order-invoice-detail" class="detail"></p></section></div></section>
<script>(()=>{const $=selector=>document.querySelector(selector),modal=$('#order-invoice-modal'),openButton=$('#open-order-invoice'),closeButton=$('#close-order-invoice'),tabs=[...document.querySelectorAll('#order-invoice-tabs [role="tab"]')],tabPanel=$('#order-invoice-tabpanel'),query=$('#order-invoice-query'),authority=$('#order-invoice-authority'),status=$('#order-invoice-status'),results=$('#order-invoice-results'),detail=$('#order-invoice-detail'),lineWindow=$('#order-invoice-line-window'),languageToggle=$('#order-invoice-language-toggle'),pageJump=$('#order-invoice-page-jump'),pageLabel=$('#order-invoice-page-label'),previousPage=$('#order-invoice-prev-page'),nextPage=$('#order-invoice-next-page');let invoker=openButton,activeIndex=0,selected=null,linePage=null,browseOffset=0,lineOffset=0,browseHasNext=false,currentLanguage='english',requestGeneration=0;const labels={source_order:'SOURCE ORDER · READ-ONLY',source_invoice:'LEGACY INVOICES · READ-ONLY',core_draft:'CORE DRAFT · LOCAL'};function clearLinePage(){linePage=null;lineOffset=0;lineWindow.replaceChildren();detail.textContent=''}function selectedType(){return tabs[activeIndex].dataset.type}function invalidateRequests(){requestGeneration+=1}function updateTabs(){tabs.forEach((tab,tabIndex)=>{const active=tabIndex===activeIndex;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1});tabPanel.setAttribute('aria-labelledby',tabs[activeIndex].id)}function updatePager(){const lineMode=Boolean(linePage),offset=lineMode?lineOffset:browseOffset,size=lineMode?250:50;previousPage.disabled=offset===0;nextPage.disabled=lineMode?linePage.next_offset===null:!browseHasNext;previousPage.textContent=lineMode?'Previous line page':'Previous results page';nextPage.textContent=lineMode?'Next line page':'Next results page';pageLabel.firstChild.textContent=lineMode?'Line page ':'Results page ';pageJump.value=String(Math.floor(offset/size)+1)}function setFilter(index){invalidateRequests();activeIndex=(index+tabs.length)%tabs.length;updateTabs();authority.textContent=labels[selectedType()];selected=null;browseOffset=0;browseHasNext=false;clearLinePage();results.replaceChildren();updatePager();status.textContent='Enter a search value to browse the selected records.'}function close(){invalidateRequests();modal.hidden=true;invoker.focus()}function focusable(){return [...modal.querySelectorAll('button:not([disabled]),input:not([disabled])')].filter(node=>!node.hidden)}function trap(event){const nodes=focusable();if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}function open(){invoker=document.activeElement instanceof HTMLElement?document.activeElement:openButton;modal.hidden=false;setFilter(activeIndex);tabs[activeIndex].focus()}function textFor(record){if(record.record_type==='source_order')return [record.order_id,record.order_date,record.customer_id].filter(Boolean).join(' · ');if(record.record_type==='source_invoice')return [record.source_invoice_number,record.invoice_date,record.customer_id,record.customer_name].filter(Boolean).join(' · ');return [record.draft_id,record.status,record.created_by,record.created_at].filter(Boolean).join(' · ')}function render(payload){results.replaceChildren();selected=null;clearLinePage();status.textContent=String(payload.total||0)+' result(s)';for(const record of payload.results||[]){const row=document.createElement('li'),button=document.createElement('button'),meta=document.createElement('span');button.type='button';button.className='result';button.textContent=textFor(record);button.setAttribute('aria-pressed','false');meta.className='meta';meta.textContent=labels[record.record_type]||'';button.append(meta);button.addEventListener('click',()=>{[...results.querySelectorAll('.result')].forEach(node=>node.setAttribute('aria-pressed','false'));button.setAttribute('aria-pressed','true');invalidateRequests();clearLinePage();updatePager();selected=record});row.append(button);results.append(row)}updatePager()}async function browse(offset=browseOffset){const value=query.value.trim(),type=selectedType(),generation=++requestGeneration;if(!value){status.textContent='Enter a search value to browse the selected records.';results.replaceChildren();return}browseOffset=offset;const params=new URLSearchParams({type,query:value,limit:'50',offset:String(browseOffset)});status.textContent='Browsing…';try{const response=await fetch('api/browse?type='+encodeURIComponent(params.get('type'))+'&query='+encodeURIComponent(params.get('query'))+'&limit='+params.get('limit')+'&offset='+params.get('offset'),{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error();const payload=await response.json();if(generation!==requestGeneration||type!==selectedType()||modal.hidden)return;browseHasNext=payload.next_offset!==null;render(payload)}catch(_){if(generation!==requestGeneration||type!==selectedType()||modal.hidden)return;results.replaceChildren();status.textContent='Browse unavailable for the selected records.'}}function sourceLineReference(record,line){return record.record_type+':'+String(record.order_id||'')+':'+String(line.line_no||'')}function renderLinePage(payload){lineWindow.replaceChildren();lineWindow.dataset.language=currentLanguage;for(const line of payload.lines||[]){const row=document.createElement('button'),provenance=currentLanguage==='thai'?line.description_th_provenance:line.description_en_provenance,description=currentLanguage==='thai'?line.description_th:line.description_en,descriptionLabel=provenance==='order'?'Order description':provenance==='item_master'?'Item master description':'',subCustomer=line.sub_customer?'Sub customer '+line.sub_customer:'';row.type='button';row.className='result';row.dataset.line='true';row.dataset.lineRef=sourceLineReference(selected,line);row.textContent=[line.line_no,line.item_id,line.qty,description,descriptionLabel,subCustomer].filter(Boolean).join(' · ');row.addEventListener('click',()=>{detail.textContent='Selected line '+(line.line_no||'')+' (read-only).'});lineWindow.append(row)}}function toggleLanguage(){if(!linePage){status.textContent='Open a Source Order to switch line descriptions.';return}currentLanguage=currentLanguage==='english'?'thai':'english';languageToggle.setAttribute('aria-pressed',String(currentLanguage==='thai'));languageToggle.textContent=currentLanguage==='thai'?'EN':'ไทย';renderLinePage(linePage);status.textContent='Line page '+pageJump.value+' of '+Math.max(1,Math.ceil(linePage.total/250))+' · '+(currentLanguage==='thai'?'Thai':'English')+' descriptions.'}async function openSourceOrder(offset=0){if(!selected||selected.record_type!=='source_order')return;const record=selected,generation=++requestGeneration;status.textContent='Opening lines…';try{const response=await fetch('api/source-orders/'+encodeURIComponent(record.order_id)+'?limit=250&offset='+encodeURIComponent(String(offset)),{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error();const payload=await response.json();if(generation!==requestGeneration||selected!==record||selectedType()!=='source_order'||modal.hidden)return;linePage=payload;lineOffset=linePage.offset;renderLinePage(linePage);updatePager();detail.textContent='Opened '+linePage.order_id+' · '+String(linePage.total)+' line(s) · read-only.';status.textContent='Line page '+pageJump.value+' of '+Math.max(1,Math.ceil(linePage.total/250))+'.'}catch(_){if(generation!==requestGeneration||selected!==record||selectedType()!=='source_order'||modal.hidden)return;lineWindow.replaceChildren();status.textContent='Order lines unavailable.'}}async function openSourceInvoice(offset=0){if(!selected||selected.record_type!=='source_invoice')return;const record=selected,generation=++requestGeneration;status.textContent='Opening legacy invoice…';try{const response=await fetch('api/source-invoices/'+encodeURIComponent(record.source_invoice_number)+'?limit=250&offset='+encodeURIComponent(String(offset)),{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error();const payload=await response.json();if(generation!==requestGeneration||selected!==record||selectedType()!=='source_invoice'||modal.hidden)return;linePage=payload;lineOffset=linePage.offset;lineWindow.replaceChildren();for(const line of linePage.lines||[]){const row=document.createElement('button');row.type='button';row.className='result';row.dataset.line='true';row.textContent=[line.line_no,line.item_id,line.qty,line.description,line.price,line.amount,line.sub_customer?'Sub customer '+line.sub_customer:''].filter(Boolean).join(' · ');row.addEventListener('click',()=>{detail.textContent='Selected legacy invoice line '+(line.line_no||'')+' (read-only).'});lineWindow.append(row)}updatePager();detail.textContent='Opened '+linePage.invoice_id+' · '+String(linePage.total)+' line(s) · read-only.';status.textContent='Line page '+pageJump.value+' of '+Math.max(1,Math.ceil(linePage.total/250))+'.'}catch(_){if(generation!==requestGeneration||selected!==record||selectedType()!=='source_invoice'||modal.hidden)return;lineWindow.replaceChildren();status.textContent='Legacy invoice lines unavailable.'}}function openLinePage(offset){if(selected&&selected.record_type==='source_order')return openSourceOrder(offset);if(selected&&selected.record_type==='source_invoice')return openSourceInvoice(offset)}function openSelected(){if(!selected){detail.textContent='Select a result first.';return}openLinePage(0)}openButton.addEventListener('click',open);closeButton.addEventListener('click',close);$('#browse-order-invoice').addEventListener('click',browse);languageToggle.addEventListener('click',toggleLanguage);$('#open-order-invoice-result').addEventListener('click',openSelected);previousPage.addEventListener('click',()=>linePage?openLinePage(Math.max(0,lineOffset-250)):browse(Math.max(0,browseOffset-50)));nextPage.addEventListener('click',()=>linePage&&linePage.next_offset!==null?openLinePage(linePage.next_offset):browse(browseOffset+50));pageJump.addEventListener('change',()=>{const page=Number(pageJump.value);if(Number.isInteger(page)&&page>0){if(linePage)openLinePage((page-1)*250);else browse((page-1)*50)}});query.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();browse()}});tabs.forEach((tab,index)=>tab.addEventListener('click',()=>setFilter(index)));modal.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close();return}if(event.key==='Tab'){trap(event);return}if((event.key==='ArrowRight'||event.key==='ArrowLeft')&&event.target.getAttribute('role')==='tab'){event.preventDefault();setFilter(activeIndex+(event.key==='ArrowRight'?1:-1));tabs[activeIndex].focus()}})})();</script>"""
    return html.replace("<!-- CORE_DRAFT_TAB -->", core_draft_tab) + fixture_drawer + """</body></html>"""
